// ── Schema-2 hook declarations (EP-1) ───────────────────────────────

function hookYaml(overrides: string[] = []): string {
	// Allow callers to replace a canonical field without relying on YAML's
	// duplicate-key behavior (which is deliberately a parse error).
	const declared = new Set(overrides.map((line) => /^([a-zA-Z]+):/.exec(line)?.[1]).filter((key): key is string => !!key));
	return [
		...(declared.has("id") ? [] : ["id: turn.audit"]),
		...(declared.has("module") ? [] : ["module: ../lib/hook.mjs"]),
		...(declared.has("events") ? [] : ["events: [beforePrompt]"]),
		...(declared.has("mode") ? [] : ["mode: observe"]),
		...(declared.has("capabilities") ? [] : ["capabilities: []"]),
		...overrides,
		"",
	].join("\n");
}

describe("schema-2 hook contribution declarations (EP-1)", () => {
	it("loads only manifest-listed YAML/YML hooks with normalized metadata in manifest order", () => {
		const root = packRoot("hooks-valid", "audit-pack");
		w(path.join(root, "pack.yaml"), "name: audit-pack\n");
		w(path.join(root, "hooks", "first.yaml"), hookYaml([
			"id: audit.first",
			"events: [sessionSetup, beforePrompt]",
			"capabilities: [store, agents]",
			"budget:",
			"  maxTokens: 9000",
			"  timeoutMs: 50",
			"config:",
			"  nested: { enabled: true }",
			"activation:",
			"  requiresConfig: [apiToken]",
		]));
		w(path.join(root, "hooks", "second.yml"), hookYaml(["id: audit.second", "mode: decide", "events: [afterTurn]", "capabilities: [session]"]));
		// Never scan an unlisted declaration.
		w(path.join(root, "hooks", "unlisted.yaml"), hookYaml(["id: audit.unlisted"]));
		w(path.join(root, "lib", "hook.mjs"), "export default {};\n");

		const contributions = loadPackContributions(root, { ...manifest("audit-pack", { hooks: ["first", "second"] }), schema: 2 });
		assert.deepEqual(contributions.hooks.map((hook) => ({
			id: hook.id, module: hook.module, events: hook.events, mode: hook.mode,
			capabilities: hook.capabilities, budget: hook.budget, listName: hook.listName,
		})), [
			{
				id: "audit.first", module: "../lib/hook.mjs", events: ["sessionSetup", "beforePrompt"], mode: "observe",
				capabilities: ["store", "agents"], budget: { maxTokens: 8192, timeoutMs: 100 }, listName: "first",
			},
			{
				id: "audit.second", module: "../lib/hook.mjs", events: ["afterTurn"], mode: "decide",
				capabilities: ["session"], budget: { maxTokens: 1600, timeoutMs: 1500 }, listName: "second",
			},
		]);
		assert.deepEqual(contributions.hooks[0].config, { nested: { enabled: true } });
		assert.deepEqual(contributions.hooks[0].activation, { requiresConfig: ["apiToken"] });
		assert.equal(contributions.hooks[1].sourceFile, path.join(root, "hooks", "second.yml"));
		assert.equal(contributions.hooks[0].packRoot, root);
	});

	it("keeps opaque and bare-scalar hook config inert instead of treating it as settings", () => {
		const root = packRoot("hooks-legacy-opaque", "legacy-hook-pack");
		w(path.join(root, "pack.yaml"), "name: legacy-hook-pack\n");
		w(path.join(root, "hooks", "legacy.yaml"), hookYaml([
			"id: legacy.config",
			"config:",
			"  endpoint: https://legacy.example.test",
			"  retries: 3",
			"  metadata: { source: historic }",
		]));
		w(path.join(root, "lib", "hook.mjs"), "export default {};\n");

		const [hook] = loadPackContributions(root, { ...manifest("legacy-hook-pack", { hooks: ["legacy"] }), schema: 2 }).hooks;
		assert.deepEqual(hook.config, {
			endpoint: "https://legacy.example.test",
			retries: 3,
			metadata: { source: "historic" },
		});
		assert.equal(hook.settingsSchema, undefined);
		assert.equal(hook.settingsSchemaDiagnostic, undefined);
	});

	it("retains config-free malformed requiresConfig hooks as invalid and fails closed at runtime", () => {
		const root = packRoot("hooks-config-free-gates", "gate-pack");
		w(path.join(root, "pack.yaml"), "name: gate-pack\n");
		for (const [listName, activation] of [
			["scalar", "activation: { requiresConfig: apiToken }"],
			["empty", "activation: { requiresConfig: [] }"],
			["mixed", "activation: { requiresConfig: [apiToken, 7] }"],
		] as const) {
			w(path.join(root, "hooks", `${listName}.yaml`), hookYaml([`id: gate.${listName}`, activation]));
		}
		w(path.join(root, "providers", "scalar.yaml"), [
			"id: gate-provider", "module: ../lib/provider.js", "hooks: [beforePrompt]", "activation: { requiresConfig: apiToken }", "",
		].join("\n"));
		w(path.join(root, "lib", "hook.mjs"), "export default {};\n");
		w(path.join(root, "lib", "provider.js"), "export default {};\n");
		const manifestWithGates = { ...manifest("gate-pack", { providers: ["scalar"], hooks: ["scalar", "empty", "mixed"] }), schema: 2 };
		const contributions = loadPackContributions(root, manifestWithGates);
		assert.deepEqual(contributions.hooks.map(hook => hook.id), ["gate.scalar", "gate.empty", "gate.mixed"]);
		for (const hook of contributions.hooks) {
			assert.equal(hook.settingsSchema, undefined);
			assert.equal(typeof hook.settingsSchemaDiagnostic, "string");
		}
		assert.equal(typeof contributions.providers[0].settingsSchemaDiagnostic, "string");
		const registry = new PackContributionRegistry(() => [entry(root, "server", manifestWithGates)]);
		assert.deepEqual(registry.listProviders(undefined), [], "invalid provider config gates must not reach runtime metadata");
		assert.deepEqual(registry.listHooks(undefined), [], "invalid hook config gates must not reach runtime metadata");
	});

	it("keeps hooks canonical and empty for schema 1, absent declarations, and an empty schema-2 list", () => {
		const root = packRoot("hooks-noop", "noop-pack");
		w(path.join(root, "pack.yaml"), "name: noop-pack\n");
		w(path.join(root, "hooks", "ignored.yaml"), hookYaml());
		w(path.join(root, "lib", "hook.mjs"), "export default {};\n");
		const schema1Manifest = { ...manifest("noop-pack", { hooks: ["ignored"] }), schema: 1 };
		const schema1 = loadPackContributions(root, schema1Manifest);
		const absent = loadPackContributions(root, { ...manifest("noop-pack"), schema: 2 });
		const empty = loadPackContributions(root, { ...manifest("noop-pack", { hooks: [] }), schema: 2 });
		assert.deepEqual(loadHooks(root, schema1Manifest), []);
		assert.deepEqual(schema1.hooks, []);
		assert.deepEqual(absent.hooks, []);
		assert.deepEqual(empty.hooks, []);
	});

	it("drops malformed hook files individually with useful warnings while retaining valid siblings", () => {
		const root = packRoot("hooks-malformed", "mixed-pack");
		w(path.join(root, "pack.yaml"), "name: mixed-pack\n");
		w(path.join(root, "hooks", "good.yaml"), hookYaml(["id: mixed.good"]));
		w(path.join(root, "hooks", "bad-events.yaml"), hookYaml(["id: mixed.events", "events: [beforePrompt, beforePrompt]"]));
		w(path.join(root, "hooks", "bad-capabilities.yaml"), hookYaml(["id: mixed.capabilities", "capabilities: [network]"]));
		w(path.join(root, "hooks", "bad-mode.yaml"), hookYaml(["id: mixed.mode", "mode: mutate"]));
		w(path.join(root, "hooks", "bad-config.yaml"), hookYaml(["id: mixed.config", "config: [not, a, mapping]"]));
		w(path.join(root, "hooks", "bad-activation.yaml"), hookYaml(["id: mixed.activation", "activation:", "  requiresConfig: [apiToken, apiToken]"]));
		w(path.join(root, "lib", "hook.mjs"), "export default {};\n");
		const warn = vi.spyOn(console, "warn").mockImplementation(() => {});
		try {
			const c = loadPackContributions(root, { ...manifest("mixed-pack", { hooks: ["good", "bad-events", "bad-capabilities", "bad-mode", "bad-config", "bad-activation"] }), schema: 2 });
			assert.deepEqual(c.hooks.map((hook) => hook.id), ["mixed.good", "mixed.activation"]);
			assert.equal(typeof c.hooks[1].settingsSchemaDiagnostic, "string");
			const output = warn.mock.calls.map((args) => args.join(" ")).join("\n");
			assert.match(output, /\[pack-contributions\]/);
			for (const file of ["bad-events", "bad-capabilities", "bad-mode", "bad-config"]) assert.match(output, new RegExp(file));
		} finally {
			warn.mockRestore();
		}
	});

	it("drops unknown top-level hook keys without rejecting valid siblings or unrelated packs", () => {
		const root = packRoot("hooks-unknown-key", "mixed-pack");
		const otherRoot = packRoot("hooks-unknown-key-other", "other-pack");
		for (const [pack, name] of [[root, "mixed-pack"], [otherRoot, "other-pack"]] as const) {
			w(path.join(pack, "pack.yaml"), `name: ${name}\n`);
			w(path.join(pack, "lib", "hook.mjs"), "export default {};\n");
		}
		w(path.join(root, "hooks", "good.yaml"), hookYaml(["id: mixed.good"]));
		w(path.join(root, "hooks", "misspelled.yaml"), hookYaml(["id: mixed.misspelled", "capabilties: []"]));
		w(path.join(otherRoot, "hooks", "good.yaml"), hookYaml(["id: other.good"]));
		const mixed = { ...manifest("mixed-pack", { hooks: ["good", "misspelled"] }), schema: 2 };
		const other = { ...manifest("other-pack", { hooks: ["good"] }), schema: 2 };
		const warn = vi.spyOn(console, "warn").mockImplementation(() => {});
		try {
			assert.deepEqual(loadPackContributions(root, mixed).hooks.map((hook) => hook.id), ["mixed.good"]);
			const registry = new PackContributionRegistry(() => [entry(root, "server", mixed), entry(otherRoot, "server", other)]);
			assert.deepEqual(registry.listHooks(undefined).map((hook) => hook.id), ["mixed.good", "other.good"]);
			assert.match(warn.mock.calls.map((args) => args.join(" ")).join("\n"), /misspelled.*unknown top-level key.*capabilties/i);
		} finally {
			warn.mockRestore();
		}
	});

	it("does not read unsafe list names and treats unsafe or escaping modules as pack conflicts", () => {
		const root = packRoot("hooks-unsafe", "safe-pack");
		w(path.join(root, "pack.yaml"), "name: safe-pack\n");
		w(path.join(root, "outside.yaml"), hookYaml(["id: escaped.file"]));
		w(path.join(root, "hooks", "ok.yaml"), hookYaml(["id: safe.ok"]));
		w(path.join(root, "hooks", "escape.yaml"), hookYaml(["id: safe.escape", "module: ../../../outside.mjs"]));
		w(path.join(root, "lib", "hook.mjs"), "export default {};\n");
		const warn = vi.spyOn(console, "warn").mockImplementation(() => {});
		try {
			const safe = loadPackContributions(root, { ...manifest("safe-pack", { hooks: ["../outside", "ok"] }), schema: 2 });
			assert.deepEqual(safe.hooks.map((hook) => hook.id), ["safe.ok"]);
			assert.match(warn.mock.calls.map((args) => args.join(" ")).join("\n"), /safe basename/i);
		} finally {
			warn.mockRestore();
		}
		assert.throws(
			() => loadPackContributions(root, { ...manifest("safe-pack", { hooks: ["escape"] }), schema: 2 }),
			(error: unknown) => error instanceof PackContributionError && /module.*outside|unsafe/i.test(error.message),
		);
	});

	it("rejects duplicate manifest refs and duplicate valid IDs within a pack", () => {
		const root = packRoot("hooks-duplicates", "dup-pack");
		w(path.join(root, "pack.yaml"), "name: dup-pack\n");
		w(path.join(root, "hooks", "a.yaml"), hookYaml(["id: duplicate"]));
		w(path.join(root, "hooks", "b.yaml"), hookYaml(["id: duplicate"]));
		w(path.join(root, "lib", "hook.mjs"), "export default {};\n");
		assert.throws(
			() => loadPackContributions(root, { ...manifest("dup-pack", { hooks: ["a", "a"] }), schema: 2 }),
			(error: unknown) => error instanceof PackContributionError && /hook listName "a"/i.test(error.message),
		);
		assert.throws(
			() => loadPackContributions(root, { ...manifest("dup-pack", { hooks: ["a", "b"] }), schema: 2 }),
			(error: unknown) => error instanceof PackContributionError && /hook id "duplicate"/i.test(error.message),
		);
	});

	it("never imports or invokes a declared hook module while loading or listing", () => {
		const root = packRoot("hooks-inert", "inert-pack");
		w(path.join(root, "pack.yaml"), "name: inert-pack\n");
		w(path.join(root, "hooks", "throwing.yaml"), hookYaml(["id: inert.throwing"]));
		w(path.join(root, "lib", "hook.mjs"), "throw new Error('hook module must not execute');\n");
		const m = { ...manifest("inert-pack", { hooks: ["throwing"] }), schema: 2 };
		assert.doesNotThrow(() => loadPackContributions(root, m));
		const registry = new PackContributionRegistry(() => [entry(root, "server", m)]);
		assert.deepEqual(registry.listHooks(undefined).map((hook) => hook.id), ["inert.throwing"]);
	});
});

// ── Hard conflicts (§5.4) ──────────────────────────────────────────

describe("hard conflicts (§5.4)", () => {
	it("duplicate panel id within a pack → PackContributionError", () => {
		const root = packRoot("c1", "p");
		w(path.join(root, "pack.yaml"), "name: p\n");
		w(path.join(root, "panels", "a.yaml"), "id: dup\nentry: lib/a.js\n");
		w(path.join(root, "panels", "b.yaml"), "id: dup\nentry: lib/b.js\n");
		assert.throws(() => loadPackContributions(root, manifest("p")), (e) => e instanceof PackContributionError && /panel id "dup"/.test(e.message));
	});

	it("duplicate entrypoint id within a pack → PackContributionError", () => {
		const root = packRoot("c2", "p");
		w(path.join(root, "pack.yaml"), "name: p\n");
		w(path.join(root, "entrypoints", "x.yaml"), "id: dup\nkind: composer-slash\nlabel: X\ntarget:\n  panelId: a\n");
		w(path.join(root, "entrypoints", "y.yaml"), "id: dup\nkind: composer-slash\nlabel: Y\ntarget:\n  panelId: b\n");
		assert.throws(() => loadPackContributions(root, manifest("p", { entrypoints: ["x", "y"] })), (e) => e instanceof PackContributionError && /entrypoint id "dup"/.test(e.message));
	});

	it("duplicate route name within a pack → PackContributionError", () => {
		const root = packRoot("c3", "p");
		w(path.join(root, "pack.yaml"), "name: p\n");
		assert.throws(() => loadPackContributions(root, manifest("p", { routes: { module: "lib/r.mjs", names: ["bundle", "bundle"] } })), (e) => e instanceof PackContributionError && /route name "bundle"/.test(e.message));
	});

	it("duplicate channel name within a pack → PackContributionError", () => {
		const root = packRoot("c3-channel", "p");
		w(path.join(root, "pack.yaml"), "name: p\n");
		w(path.join(root, "channels", "a.yaml"), "name: dup\nmodule: ../lib/a.mjs\n");
		w(path.join(root, "channels", "b.yaml"), "name: dup\nmodule: ../lib/b.mjs\n");
		assert.throws(() => loadPackContributions(root, { ...manifest("p", { channels: ["a", "b"] }), schema: 2 }), (e) => e instanceof PackContributionError && /channel name "dup"/.test(e.message));
	});

	it("duplicate host-global routeId across DISTINCT packs → registry registers NEITHER deep-link", () => {
		const rootA = packRoot("c4a", "packA");
		const rootB = packRoot("c4b", "packB");
		for (const [root, name] of [[rootA, "packA"], [rootB, "packB"]] as const) {
			w(path.join(root, "pack.yaml"), `name: ${name}\n`);
			w(path.join(root, "entrypoints", "dl.yaml"), "id: dl\nkind: route\nrouteId: shared\ntarget:\n  panelId: a\nparamKeys: []\n");
		}
		const reg = new PackContributionRegistry(() => [
			entry(rootA, "server", manifest("packA", { entrypoints: ["dl"] })),
			entry(rootB, "global-user", manifest("packB", { entrypoints: ["dl"] })),
		]);
		// Both packs drop the conflicting deep-link entrypoint.
		assert.equal(reg.getPack(undefined, "packA")!.entrypoints.length, 0);
		assert.equal(reg.getPack(undefined, "packB")!.entrypoints.length, 0);
	});
});

// ── Registry: precedence collapse + activation filtering + always-emit ──

describe("PackContributionRegistry (§5.2.1, §7)", () => {
	it("keeps valid hooks from unrelated packs when a conflicting hook pack is rejected", () => {
		const badRoot = packRoot("hooks-registry-bad", "bad-hooks");
		const goodRoot = packRoot("hooks-registry-good", "good-hooks");
		for (const [root, name] of [[badRoot, "bad-hooks"], [goodRoot, "good-hooks"]] as const) {
			w(path.join(root, "pack.yaml"), `name: ${name}\n`);
			w(path.join(root, "lib", "hook.mjs"), "export default {};\n");
		}
		w(path.join(badRoot, "hooks", "a.yaml"), hookYaml(["id: duplicate"]));
		w(path.join(badRoot, "hooks", "b.yaml"), hookYaml(["id: duplicate"]));
		w(path.join(goodRoot, "hooks", "good.yaml"), hookYaml(["id: good.hook"]));
		const error = vi.spyOn(console, "error").mockImplementation(() => {});
		try {
			const registry = new PackContributionRegistry(() => [
				entry(badRoot, "server", { ...manifest("bad-hooks", { hooks: ["a", "b"] }), schema: 2 }),
				entry(goodRoot, "server", { ...manifest("good-hooks", { hooks: ["good"] }), schema: 2 }),
			]);
			assert.equal(registry.getPack(undefined, "bad-hooks"), undefined);
			assert.deepEqual(registry.listHooks(undefined).map((hook) => hook.id), ["good.hook"]);
			assert.match(error.mock.calls.map((args) => args.join(" ")).join("\n"), /rejecting pack/i);
		} finally {
			error.mockRestore();
		}
	});

	it("listHooks preserves winning-pack and manifest order while cross-pack equal IDs remain distinct", () => {
		const shadowedRoot = packRoot("hooks-order-global", "shared");
		const winningRoot = packRoot("hooks-order-project", "shared");
		const otherRoot = packRoot("hooks-order-other", "other");
		for (const [root, name] of [[shadowedRoot, "shared"], [winningRoot, "shared"], [otherRoot, "other"]] as const) {
			w(path.join(root, "pack.yaml"), `name: ${name}\n`);
			w(path.join(root, "lib", "hook.mjs"), "export default {};\n");
		}
		w(path.join(shadowedRoot, "hooks", "old.yaml"), hookYaml(["id: shadowed.old"]));
		w(path.join(winningRoot, "hooks", "first.yaml"), hookYaml(["id: same.id"]));
		w(path.join(winningRoot, "hooks", "second.yaml"), hookYaml(["id: shared.second"]));
		w(path.join(otherRoot, "hooks", "only.yaml"), hookYaml(["id: same.id"]));
		const registry = new PackContributionRegistry(() => [
			entry(shadowedRoot, "global-user", { ...manifest("shared", { hooks: ["old"] }), schema: 2 }),
			entry(otherRoot, "server", { ...manifest("other", { hooks: ["only"] }), schema: 2 }),
			entry(winningRoot, "project", { ...manifest("shared", { hooks: ["first", "second"] }), schema: 2 }),
		]);
		assert.deepEqual(registry.listHooks(undefined).map((hook) => `${hook.packRoot}:${hook.id}`), [
			`${winningRoot}:same.id`,
			`${winningRoot}:shared.second`,
			`${otherRoot}:same.id`,
		]);
		assert.deepEqual(registry.getPack(undefined, "shared")!.hooks.map((hook) => hook.id), ["same.id", "shared.second"]);
	});

	it("activation filtering removes disabled hook list names after invalidation and restores them", () => {
		const root = packRoot("hooks-activation", "active-hooks");
		w(path.join(root, "pack.yaml"), "name: active-hooks\n");
		w(path.join(root, "hooks", "first.yaml"), hookYaml(["id: active.first"]));
		w(path.join(root, "hooks", "second.yaml"), hookYaml(["id: active.second"]));
		w(path.join(root, "lib", "hook.mjs"), "export default {};\n");
		let disabled: string[] = [];
		const m = { ...manifest("active-hooks", { hooks: ["first", "second"] }), schema: 2 };
		const registry = new PackContributionRegistry(
			() => [entry(root, "server", m)],
			undefined,
			undefined,
			undefined,
			(_scope, _projectId, packName) => packName === "active-hooks" ? disabled : [],
		);
		assert.deepEqual(registry.listHooks(undefined).map((hook) => hook.listName), ["first", "second"]);
		disabled = ["first"];
		assert.deepEqual(registry.getPack(undefined, "active-hooks")!.hooks.map((hook) => hook.listName), ["first", "second"], "cache remains stable before invalidation");
		registry.invalidate();
		assert.deepEqual(registry.getPack(undefined, "active-hooks")!.hooks.map((hook) => hook.listName), ["second"]);
		assert.deepEqual(registry.listHooks(undefined).map((hook) => hook.listName), ["second"]);
		disabled = [];
		registry.invalidate();
		assert.deepEqual(registry.listHooks(undefined).map((hook) => hook.listName), ["first", "second"]);
	});

	it("winning-pack collapse: same packId at two scopes → ONE getPack (the highest-precedence variant)", () => {
		const gRoot = packRoot("collapse-global", "artifacts");
		const pRoot = packRoot("collapse-project", "artifacts");
		w(path.join(gRoot, "pack.yaml"), "name: artifacts\n");
		w(path.join(gRoot, "panels", "g.yaml"), "id: global.panel\nentry: lib/g.js\n");
		w(path.join(pRoot, "pack.yaml"), "name: artifacts\n");
		w(path.join(pRoot, "panels", "p.yaml"), "id: project.panel\nentry: lib/p.js\n");
		assert.equal(packIdFromRoot(gRoot), "artifacts");
		assert.equal(packIdFromRoot(pRoot), "artifacts");
		// Enumerate low→high: global-user THEN project (project wins).
		const reg = new PackContributionRegistry(() => [
			entry(gRoot, "global-user", manifest("artifacts")),
			entry(pRoot, "project", manifest("artifacts")),
		]);
		const all = reg.list(undefined);
		assert.equal(all.filter((p) => p.packId === "artifacts").length, 1);
		const pack = reg.getPack(undefined, "artifacts")!;
		assert.deepEqual(pack.panels.map((p) => p.id), ["project.panel"]);
	});

	it("getChannel resolves a channel by packId/name without exposing module paths to wire metadata", () => {
		const root = packRoot("reg-channel", "terminal-pack");
		w(path.join(root, "pack.yaml"), "name: terminal-pack\n");
		w(path.join(root, "channels", "terminal.yaml"), "name: terminal\nmodule: ../lib/channel.mjs\n");
		w(path.join(root, "lib", "channel.mjs"), "export default {};\n");
		const m = { ...manifest("terminal-pack", { channels: ["terminal"] }), schema: 2 };
		const reg = new PackContributionRegistry(() => [entry(root, "server", m)]);
		const channel = reg.getChannel(undefined, "terminal-pack", "terminal")!;
		assert.equal(channel.name, "terminal");
		assert.equal(channel.module, "../lib/channel.mjs");
		const wire = { packId: reg.getPack(undefined, "terminal-pack")!.packId, channelNames: reg.getPack(undefined, "terminal-pack")!.channels.map((c) => c.name) };
		assert.deepEqual(wire, { packId: "terminal-pack", channelNames: ["terminal"] });
		assert.equal(Object.hasOwn(wire, "module"), false);
	});

	it("preserves declared sessionPty capabilities for trusted packs", () => {
		const thirdPartyRoot = packRoot("reg-channel-auth-user", "third-party");
		const builtinRoot = packRoot("reg-channel-auth-builtin", "builtin-terminal");
		for (const [root, name] of [[thirdPartyRoot, "third-party"], [builtinRoot, "builtin-terminal"]] as const) {
			w(path.join(root, "pack.yaml"), `name: ${name}\n`);
			w(path.join(root, "channels", "terminal.yaml"), "name: terminal\nmodule: ../lib/channel.mjs\ncapabilities: [sessionPty, futurePower]\n");
			w(path.join(root, "lib", "channel.mjs"), "export default {};\n");
		}
		const thirdPartyManifest = { ...manifest("third-party", { channels: ["terminal"] }), schema: 2 };
		const builtinManifest = { ...manifest("builtin-terminal", { channels: ["terminal"] }), schema: 2 };
		const builtinEntry: PackEntry = {
			...entry(builtinRoot, "server", builtinManifest),
			id: "builtin-pack:builtin-terminal",
			readOnly: true,
			meta: { sourceUrl: "builtin:", sourceRef: "", commit: "", packName: "builtin-terminal", version: "1", installedAt: "", updatedAt: "", scope: "server" },
		};
		const reg = new PackContributionRegistry(() => [
			entry(thirdPartyRoot, "project", thirdPartyManifest),
			builtinEntry,
		]);
		assert.deepEqual(reg.getChannel(undefined, "third-party", "terminal")!.capabilities, ["sessionPty"]);
		assert.deepEqual(reg.getChannel(undefined, "builtin-terminal", "terminal")!.capabilities, ["sessionPty"]);
	});

	it("activation filtering: a disabled entrypoint is omitted; panels stay present", () => {
		const root = packRoot("act", "artifacts");
		w(path.join(root, "pack.yaml"), "name: artifacts\n");
		w(path.join(root, "panels", "v.yaml"), "id: artifacts.viewer\nentry: lib/v.js\n");
		w(path.join(root, "entrypoints", "artifacts-deeplink.yaml"), "id: artifacts.deeplink\nkind: route\nrouteId: artifacts\ntarget:\n  panelId: artifacts.viewer\nparamKeys: []\n");
		const m = manifest("artifacts", { entrypoints: ["artifacts-deeplink"] });
		// No activation override → entrypoint present.
		const enabled = new PackContributionRegistry(() => [entry(root, "server", m)]);
		assert.equal(enabled.getPack(undefined, "artifacts")!.entrypoints.length, 1);
		// Disable the entrypoint by listName → omitted; panel still present.
		const filtered = new PackContributionRegistry(
			() => [entry(root, "server", m)],
			(_scope, _pid, packName) => (packName === "artifacts" ? ["artifacts-deeplink"] : []),
		);
		const pack = filtered.getPack(undefined, "artifacts")!;
		assert.equal(pack.entrypoints.length, 0);
		assert.equal(pack.panels.length, 1);
	});

	it("activation filtering: a disabled provider is omitted and re-enabled by removing the ref", () => {
		const root = packRoot("act-provider", "memory-pack");
		w(path.join(root, "pack.yaml"), "name: memory-pack\n");
		w(path.join(root, "providers", "memory.yaml"), "id: memory\nmodule: ../lib/provider.js\nhooks: [beforePrompt]\n");
		w(path.join(root, "lib", "provider.js"), "export default {};\n");
		const m = { ...manifest("memory-pack", { providers: ["memory"] }), schema: 2 };
		const enabled = new PackContributionRegistry(() => [entry(root, "server", m)]);
		assert.deepEqual(enabled.listProviders(undefined).map((p) => p.id), ["memory"]);

		const filtered = new PackContributionRegistry(
			() => [entry(root, "server", m)],
			undefined,
			(_scope, _pid, packName) => (packName === "memory-pack" ? ["memory"] : []),
		);
		assert.deepEqual(filtered.listProviders(undefined).map((p) => p.id), []);

		const restored = new PackContributionRegistry(() => [entry(root, "server", m)], undefined, () => []);
		assert.deepEqual(restored.listProviders(undefined).map((p) => p.id), ["memory"]);
		assert.equal(restored.getPack(undefined, "memory-pack")!.entrypoints.length, 0, "entrypoint filtering remains unchanged");
	});

	it("fails closed invalid provider settings before defaults, legacy overlays, or runtime exposure", () => {
		const root = packRoot("invalid-provider-settings", "mixed-provider-pack");
		w(path.join(root, "pack.yaml"), "name: mixed-provider-pack\n");
		w(path.join(root, "panels", "status.yaml"), "id: mixed.status\nentry: ../lib/status.js\n");
		w(path.join(root, "providers", "invalid.yaml"), [
			"id: invalid", "module: ../lib/provider.js", "hooks: [beforePrompt]", "config:",
			"  externalUrl: { type: diagnostic-secret, default: https://default.invalid }",
			"activation:", "  requiresConfig: [externalUrl]", "",
		].join("\n"));
		w(path.join(root, "providers", "valid.yaml"), [
			"id: valid", "module: ../lib/provider.js", "hooks: [beforePrompt]", "config:",
			"  externalUrl: { type: string, default: https://default.valid }",
			"activation:", "  requiresConfig: [externalUrl]", "",
		].join("\n"));
		w(path.join(root, "lib", "provider.js"), "export default {};\n");
		const m = { ...manifest("mixed-provider-pack", { providers: ["invalid", "valid"] }), schema: 2 };
		const settingsReads: string[] = [];
		const legacyReads: string[] = [];
		const warning = vi.spyOn(console, "warn").mockImplementation(() => {});
		try {
			const registry = new PackContributionRegistry(
				() => [entry(root, "server", m)], undefined, undefined,
				(_scope, _projectId, _packId, providerId) => {
					legacyReads.push(providerId);
					return { externalUrl: `https://legacy.${providerId}` };
				},
				undefined, undefined, undefined,
				(_projectId, _packId, kind, id) => {
					settingsReads.push(`${kind}:${id ?? ""}`);
					return { state: "absent" };
				},
			);
			assert.deepEqual(registry.listProviders(undefined).map((provider) => provider.id), ["valid"]);
			assert.deepEqual(registry.listProviders(undefined)[0].config, { externalUrl: "https://legacy.valid" });
			assert.equal(registry.getPack(undefined, "mixed-provider-pack")?.panels[0]?.id, "mixed.status");
			assert.deepEqual(legacyReads, ["valid"], "invalid declarations must not reach legacy settings");
			assert.equal(settingsReads.includes("provider:invalid"), false, "invalid declarations must not read project settings");
			assert.doesNotMatch(warning.mock.calls.flat().join("\n"), /diagnostic-secret/);
		} finally {
			warning.mockRestore();
		}
	});

	it("fails closed invalid hook settings without dropping the pack or valid hook siblings", () => {
		const root = packRoot("invalid-hook-settings", "mixed-hook-pack");
		w(path.join(root, "pack.yaml"), "name: mixed-hook-pack\n");
		w(path.join(root, "panels", "status.yaml"), "id: mixed.status\nentry: ../lib/status.js\n");
		w(path.join(root, "hooks", "invalid.yaml"), hookYaml([
			"id: invalid", "config:", "  apiKey: { type: diagnostic-secret }",
		]));
		w(path.join(root, "hooks", "valid.yaml"), hookYaml([
			"id: valid", "config:", "  enabled: { type: boolean, default: true }",
		]));
		w(path.join(root, "lib", "hook.mjs"), "export default {};\n");
		const m = { ...manifest("mixed-hook-pack", { hooks: ["invalid", "valid"] }), schema: 2 };
		const settingsReads: string[] = [];
		const warning = vi.spyOn(console, "warn").mockImplementation(() => {});
		try {
			const registry = new PackContributionRegistry(
				() => [entry(root, "server", m)], undefined, undefined, undefined, undefined, undefined, undefined,
				(_projectId, _packId, kind, id) => {
					settingsReads.push(`${kind}:${id ?? ""}`);
					return { state: "present", enabled: true, values: {} };
				},
			);
			assert.deepEqual(registry.listHooks(undefined).map((hook) => hook.id), ["valid"]);
			assert.equal(registry.getPack(undefined, "mixed-hook-pack")?.panels[0]?.id, "mixed.status");
			assert.equal(settingsReads.includes("hook:invalid"), false, "invalid declarations must not read project settings");
			assert.equal(settingsReads.includes("hook:valid"), true);
			assert.doesNotMatch(warning.mock.calls.flat().join("\n"), /diagnostic-secret/);
		} finally {
			warning.mockRestore();
		}
	});

	it("config-gated activation: a provider with requiresConfig is omitted until the override supplies the key", () => {
		const root = packRoot("act-config", "memory-pack");
		w(path.join(root, "pack.yaml"), "name: memory-pack\n");
		w(path.join(root, "providers", "memory.yaml"), [
			"id: memory",
			"module: ../lib/provider.js",
			"hooks: [beforePrompt]",
			"config:",
			"  externalUrl: { type: string, optional: true }",
			"  bank: { type: string, default: bobbit }",
			"activation:",
			"  requiresConfig: [externalUrl]",
			"",
		].join("\n"));
		w(path.join(root, "lib", "provider.js"), "export default {};\n");
		const m = { ...manifest("memory-pack", { providers: ["memory"] }), schema: 2 };

		// No override → externalUrl absent → provider dormant (omitted): no bridge.
		const dormant = new PackContributionRegistry(() => [entry(root, "server", m)]);
		assert.deepEqual(dormant.listProviders(undefined).map((p) => p.id), []);

		// Empty-string override does NOT satisfy the gate.
		const blank = new PackContributionRegistry(
			() => [entry(root, "server", m)], undefined, undefined,
			() => ({ externalUrl: "   " }),
		);
		assert.deepEqual(blank.listProviders(undefined).map((p) => p.id), []);

		// Non-empty externalUrl override → provider becomes active with EFFECTIVE
		// flat config = schema defaults overlaid with the override.
		const configured = new PackContributionRegistry(
			() => [entry(root, "server", m)], undefined, undefined,
			(_s, _pid, packId, providerId) => (packId === "memory-pack" && providerId === "memory" ? { externalUrl: "http://localhost:8888" } : undefined),
		);
		const active = configured.listProviders(undefined);
		assert.deepEqual(active.map((p) => p.id), ["memory"]);
		assert.deepEqual(active[0].config, { externalUrl: "http://localhost:8888", bank: "bobbit" });
	});

	it("does not activate or cache a provider when durable config is unreadable, then retries", () => {
		const root = packRoot("act-config-read-error", "memory-pack");
		w(path.join(root, "pack.yaml"), "name: memory-pack\n");
		w(path.join(root, "providers", "memory.yaml"), [
			"id: memory",
			"module: ../lib/provider.js",
			"hooks: [beforePrompt]",
			"config:",
			"  bank: { type: string, default: bobbit }",
			"",
		].join("\n"));
		w(path.join(root, "lib", "provider.js"), "export default {};\n");
		const m = { ...manifest("memory-pack", { providers: ["memory"] }), schema: 2 };
		let reads = 0;
		const warning = vi.spyOn(console, "warn").mockImplementation(() => {});
		const registry = new PackContributionRegistry(
			() => [entry(root, "server", m)], undefined, undefined,
			() => {
				reads++;
				return reads === 1
					? { state: "error" as const, diagnostic: { code: "STORE_READ_IO", retryable: true, path: "/must-not-leak" } }
					: { state: "present" as const, value: { bank: "recovered" } };
			},
		);
		try {
			assert.deepEqual(registry.listProviders(undefined), [], "unreadable config must fail closed even for an unconditional provider");
			assert.deepEqual(registry.listProviders(undefined).map((p) => p.config), [{ bank: "recovered" }]);
			assert.equal(reads, 2, "a read error must not become a permanently cached empty/default config");
			assert.doesNotMatch(warning.mock.calls.join("\n"), /must-not-leak/);
		} finally {
			warning.mockRestore();
		}
	});

	it("config overlay: store override wins over the schema default for an unconditional provider", () => {
		const root = packRoot("cfg-overlay", "memory-pack");
		w(path.join(root, "pack.yaml"), "name: memory-pack\n");
		w(path.join(root, "providers", "memory.yaml"), [
			"id: memory",
			"module: ../lib/provider.js",
			"hooks: [beforePrompt]",
			"config:",
			"  bank: { type: string, default: bobbit }",
			"  autoRecall: { type: boolean, default: true }",
			"",
		].join("\n"));
		w(path.join(root, "lib", "provider.js"), "export default {};\n");
		const m = { ...manifest("memory-pack", { providers: ["memory"] }), schema: 2 };

		const reg = new PackContributionRegistry(
			() => [entry(root, "server", m)], undefined, undefined,
			() => ({ bank: "custom", autoRecall: false }),
		);
		const [p] = reg.listProviders(undefined);
		assert.deepEqual(p.config, { bank: "custom", autoRecall: false });
	});

	it("DisabledRefs still wins over config-gated activation (kill switch first)", () => {
		const root = packRoot("act-disabled-wins", "memory-pack");
		w(path.join(root, "pack.yaml"), "name: memory-pack\n");
		w(path.join(root, "providers", "memory.yaml"), [
			"id: memory",
			"module: ../lib/provider.js",
			"hooks: [beforePrompt]",
			"config:",
			"  externalUrl: { type: string, optional: true }",
			"activation:",
			"  requiresConfig: [externalUrl]",
			"",
		].join("\n"));
		w(path.join(root, "lib", "provider.js"), "export default {};\n");
		const m = { ...manifest("memory-pack", { providers: ["memory"] }), schema: 2 };

		// Configured AND disabled → still omitted (DisabledRefs is the kill switch).
		const reg = new PackContributionRegistry(
			() => [entry(root, "server", m)],
			undefined,
			(_s, _p, packName) => (packName === "memory-pack" ? ["memory"] : []),
			() => ({ externalUrl: "http://localhost:8888" }),
		);
		assert.deepEqual(reg.listProviders(undefined).map((p) => p.id), []);
	});

	it("always-emit: an installed pack with no panels/entrypoints/routes still produces a list row", () => {
		const root = packRoot("empty", "bare");
		w(path.join(root, "pack.yaml"), "name: bare\n");
		const reg = new PackContributionRegistry(() => [entry(root, "server", manifest("bare"))]);
		const rows = reg.list(undefined);
		assert.equal(rows.length, 1);
		assert.deepEqual({ panels: rows[0].panels.length, entrypoints: rows[0].entrypoints.length, routes: rows[0].routes }, { panels: 0, entrypoints: 0, routes: undefined });
	});

	it("invalidate() drops the per-project cache", () => {
		const root = packRoot("inval", "p");
		w(path.join(root, "pack.yaml"), "name: p\n");
		let panels = true;
		if (panels) w(path.join(root, "panels", "a.yaml"), "id: a.panel\nentry: lib/a.js\n");
		const reg = new PackContributionRegistry(() => [entry(root, "server", manifest("p"))]);
		assert.equal(reg.getPack(undefined, "p")!.panels.length, 1);
		fs.rmSync(path.join(root, "panels", "a.yaml"));
		// Cached until invalidate().
		assert.equal(reg.getPack(undefined, "p")!.panels.length, 1);
		reg.invalidate();
		assert.equal(reg.getPack(undefined, "p")!.panels.length, 0);
	});
});
